import numpy as np,json
from PIL import Image
cam='egocentric_mirrored_camera';m=json.load(open('/app/output/held/meta.json'));im=np.array(Image.open(f'/app/output/held/{cam}.png'));d=np.load(f'/app/output/held/{cam}_depth.npy');K=np.array(m['cameras'][cam]['intrinsic_cv']);E=np.array(m['cameras'][cam]['extrinsic_cv']);R,G,B=np.moveaxis(im.astype(int),2,0);Y,X=np.ogrid[:im.shape[0],:im.shape[1]]
def cloud(mask):
 yy,xx=np.where(mask&(d>0));zz=d[yy,xx];Xc=np.stack([(xx-K[0,2])*zz/K[0,0],(yy-K[1,2])*zz/K[1,1],zz],axis=1);return (Xc-E[:,3])@E[:,:3]
for name,mask in [('banana',(X>290)&(X<430)&(Y>125)&(Y<213)&(R>145)&(G>125)&(B<110)&(R>G*.95)),('bowl',(X>480)&(X<611)&(Y>190)&(Y<300)&(R>G*1.3)&(R>B*1.15)&(R>45))]:
 w=cloud(mask);print(name,'n',len(w),'xyz 5/25/50/75/95',np.quantile(w,[.05,.25,.5,.75,.95],axis=0),'mean',w.mean(axis=0));
 if name=='bowl':
  for lo,hi in [(.003,.015),(.015,.035),(.045,.07)]:
   s=w[(w[:,2]>=lo)&(w[:,2]<hi)];print('z',lo,hi,'n',len(s),'xy 5/50/95',np.quantile(s[:,:2],[.05,.5,.95],axis=0),'mean',s[:,:2].mean(axis=0))
